 $event=Get-WinEvent -path $file -max 1 -ErrorAction Stop
 }
 catch
 {
 Write-Host "Get-WinEvent error: " $_.Exception.Message "`n"
 Write-Host "Exiting...`n"
 exit
 }
 switch ($event.LogName){
 "Security" {$logname="Security"}
